    void string(std::string_view text) {
        output << '"';
        for (const unsigned char c : text) {
            switch (c) {
                case '"': output << "\\\""; break;
                case '\\': output << "\\\\"; break;
                case '\n': output << "\\n"; break;
                case '\r': output << "\\r"; break;
                case '\t': output << "\\t"; break;
                default:
                    if (c < 0x20) output << "\\u00" << "0123456789abcdef"[c >> 4] << "0123456789abcdef"[c & 15];
                    else output << static_cast<char>(c);
            }
        }
        output << '"';
    }
    void value(const std::string& text) { string(text); }
    void value(bool number) { output << (number ? "true" : "false"); }
    void value(std::uint32_t number) { output << number; }
    void value(std::uint64_t number) {
        std::ostringstream hex; hex << std::hex << std::setfill('0') << std::setw(16) << number;
        string(hex.str());
    }
    void value(const std::vector<std::uint8_t>& bytes) {
        constexpr std::string_view alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        std::string encoded;
        for (std::size_t i = 0; i < bytes.size(); i += 3) {
            const std::uint32_t word = (std::uint32_t(bytes[i]) << 16) |
                (i + 1 < bytes.size() ? std::uint32_t(bytes[i+1]) << 8 : 0) |
                (i + 2 < bytes.size() ? std::uint32_t(bytes[i+2]) : 0);
            encoded += alphabet[(word >> 18) & 63]; encoded += alphabet[(word >> 12) & 63];
            encoded += i + 1 < bytes.size() ? alphabet[(word >> 6) & 63] : '=';
            encoded += i + 2 < bytes.size() ? alphabet[word & 63] : '=';
        }
        string(encoded);
    }
    template<class T> void value(const std::vector<T>& items) {
        output << '['; bool first = true;
        for (const auto& item : items) { if (!std::exchange(first, false)) output << ','; value(item); }
        output << ']';
    }
    template<class T> void field(bool& first, const char* key, const T& item) {
        if (!std::exchange(first, false)) output << ',';
        string(key); output << ':'; value(item);
    }
    template<class T> void field(bool& first, const char* key, const std::optional<T>& item) {
        if (item) field(first, key, *item);
    }
    static std::string tag(const std::string& native) {
        if (native == "functionEntry") return "function-entry";
        if (native == "operationResult") return "operation-result";
        if (native == "phiResult") return "phi-result";
        if (native == "switchCase") return "switch-case";
        if (native == "switchDefault") return "switch-default";
        if (native == "floatingPoint") return "floating-point";
        if (native == "doWhile") return "do-while";
        if (native == "infiniteLoop") return "infinite-loop";
        if (native == "multiGoto") return "multi-goto";
        if (native == "readWrite") return "read-write";
        return native;
    }
    void value(AuthenticationEffectKind effect) {
        switch (effect) {
            case AuthenticationEffectKind::none: string("none"); break;
            case AuthenticationEffectKind::transformedOutput: string("transformed-output"); break;
            case AuthenticationEffectKind::authenticatedMemoryAccessWithoutTransformedAddress:
                string("authenticated-memory-access-without-transformed-address"); break;
            case AuthenticationEffectKind::authenticatedControlTransferWithoutTransformedTarget:
                string("authenticated-control-transfer-without-transformed-target"); break;
            case AuthenticationEffectKind::standaloneAuthenticationWithoutTransformedOutput:
                string("standalone-authentication-without-transformed-output"); break;
        }
    }
